%--------------------------------------------------------------------------
%getCueLengths
%By: Brielle Ferguson
%Date: 12/1/24
%Will take the trial structure generated by readAnalyzePlotBehData, and
%find the number of cue lengths. See listTrialTypes to perform a similar
%function for any field (e.g., delay length, distractor intensity)
%Inputs:
% - trials: data structure with trial information from a behavioral session
%Outputs:
% - num: how many unique cue lengths there are 
% - vals: the specific values of the cue lengths
%-------------------------------------------------------------------------

function [num,values] = getCueLengths(trials)
for i = 1:length(trials)
    if ~isempty(trials(i).cuelength)
    cueLength(i) = trials(i).cuelength;
    else
    cueLength(i) = NaN;    
    end
end

values = sort(unique(cueLength),'descend');
values = values(~isnan(values));
num = length(values); 
end